/* Test of the indirect-call cache (runtime/src/dispatch.c).
 *
 * Linked with the real function table (build/gen/table.c) and, in place of the recompiled functions,
 * one stub per table entry that writes its own guest address to r0 (generated by
 * run_dispatch_cache_test.sh from build/gen/funcs.h; game-derived, so it stays under build/).
 * Checks, for tens of millions of lookups (a hot set of a few hundred targets as a frame has, the whole
 * table, addresses that are not function entries):
 *   - ppc_dispatch_lookup(a) returns exactly what the plain binary search returns (NULL for non-entries);
 *   - ppc_dispatch(c) with c->pc = a runs the stub for a (r0 = a), for a sample of them;
 *   - the same with four host threads looking up at once (the cache's one-word entries);
 * then times the binary search against the cached lookup.
 *
 * Usage: dispatch_cache_test [lookups] [seed] */
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <threads.h>
#include <time.h>

#include "recomp_table.h"
#include "runtime.h"

static int g_logs;
void rt_log(const char* fmt, ...) { (void)fmt; g_logs++; }
_Noreturn void rt_fatal(const char* fmt, ...) { va_list ap; va_start(ap, fmt); vfprintf(stderr, fmt, ap); va_end(ap); fputc('\n', stderr); exit(2); }
PpcFunc ppc_dispatch_lookup(uint32_t a);

static PpcFunc ref_search(uint32_t a) {  /* ppc_dispatch before the cache */
    unsigned lo = 0, hi = g_recomp_func_count;
    while (lo < hi) {
        unsigned mid = (lo + hi) / 2;
        if (g_recomp_funcs[mid].addr < a) lo = mid + 1; else hi = mid;
    }
    return lo < g_recomp_func_count && g_recomp_funcs[lo].addr == a ? g_recomp_funcs[lo].fn : (PpcFunc)0;
}

typedef struct { uint64_t s; } Rng;
static uint32_t rnd(Rng* r) { r->s ^= r->s << 13; r->s ^= r->s >> 7; r->s ^= r->s << 17; return (uint32_t)(r->s >> 16); }

#define HOT 600
typedef struct { uint64_t seed; long n; long bad, valid, invalid, called, call_bad; } Job;

static uint32_t pick(Rng* r, const uint32_t* hot) {
    uint32_t k = rnd(r) % 100;
    if (k < 90) {  /* skewed: a few targets very often */
        uint32_t i = rnd(r) % HOT, j = rnd(r) % HOT;
        return hot[i < j ? i : j];
    }
    if (k < 98) return g_recomp_funcs[rnd(r) % g_recomp_func_count].addr;
    if (k < 99) return g_recomp_funcs[rnd(r) % g_recomp_func_count].addr + 4u * (1 + rnd(r) % 4);  /* mostly not entries */
    return rnd(r) ^ (rnd(r) << 16);
}

static uint32_t g_hot[HOT];

static int job_run(void* arg) {
    Job* j = arg;
    Rng r = {j->seed};
    for (long i = 0; i < j->n; i++) {
        uint32_t a = pick(&r, g_hot);
        PpcFunc want = ref_search(a), got = ppc_dispatch_lookup(a);
        if (got != want) j->bad++;
        if (want) j->valid++; else j->invalid++;
        if (want && (i & 15) == 0) {
            Cpu c; memset(&c, 0, sizeof c);
            c.pc = a; c.r[0] = 0;
            ppc_dispatch(&c);
            j->called++;
            if (c.r[0] != a) j->call_bad++;
        }
    }
    return 0;
}

static double now_ns(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t); return t.tv_sec * 1e9 + t.tv_nsec; }

int main(int argc, char** argv) {
    long n = argc > 1 ? atol(argv[1]) : 20000000;
    uint64_t seed = argc > 2 ? strtoull(argv[2], NULL, 0) : 0x9E3779B97F4A7C15ull;
    Rng r = {seed};
    for (int i = 0; i < HOT; i++) g_hot[i] = g_recomp_funcs[rnd(&r) % g_recomp_func_count].addr;
    printf("table: %u functions\n", g_recomp_func_count);

    Job one = {seed ^ 1, n, 0, 0, 0, 0, 0};
    job_run(&one);
    printf("one thread: %ld lookups (%ld function entries, %ld not), %ld wrong; %ld dispatched calls, %ld ran the wrong function\n",
           one.n, one.valid, one.invalid, one.bad, one.called, one.call_bad);

    Job jobs[4];
    thrd_t t[4];
    for (int i = 0; i < 4; i++) {
        jobs[i] = (Job){seed + 101u * (uint64_t)(i + 1), n / 4, 0, 0, 0, 0, 0};
        thrd_create(&t[i], job_run, &jobs[i]);
    }
    long bad4 = 0, call_bad4 = 0, n4 = 0;
    for (int i = 0; i < 4; i++) { thrd_join(t[i], NULL); bad4 += jobs[i].bad; call_bad4 += jobs[i].call_bad; n4 += jobs[i].n; }
    printf("four threads at once: %ld lookups, %ld wrong, %ld calls ran the wrong function\n", n4, bad4, call_bad4);

    /* speed: the same skewed stream of function entries, binary search against the cache */
    {
        const long N = 20000000;
        static uint32_t stream[1 << 16];
        Rng s = {seed ^ 7};
        for (int i = 0; i < (1 << 16); i++) {
            uint32_t a;
            do a = pick(&s, g_hot); while (!ref_search(a));
            stream[i] = a;
        }
        double best[2] = {1e30, 1e30};
        uintptr_t sink = 0;
        for (int rep = 0; rep < 3; rep++)
            for (int h = 0; h < 2; h++) {
                double t0 = now_ns();
                for (long i = 0; i < N; i++) {
                    uint32_t a = stream[i & 0xFFFF];
                    sink += (uintptr_t)(h ? ppc_dispatch_lookup(a) : ref_search(a));
                }
                double dt = (now_ns() - t0) / N;
                if (dt < best[h]) best[h] = dt;
            }
        printf("host speed per lookup (90%% from %d hot targets): binary search %.1f ns, cache %.1f ns (%lu)\n",
               HOT, best[0], best[1], (unsigned long)(sink & 1));
    }
    int ok = !one.bad && !one.call_bad && !bad4 && !call_bad4 && one.invalid > 0;
    printf("RESULT: %s\n", ok ? "PASS" : "FAIL");
    return ok ? 0 : 1;
}
